// Local preview fixtures; not imported by the production app.
import 'dart:convert';
import 'package:flutter/services.dart';

class PipPreviewAssets extends CachingAssetBundle {
  @override
  Future<ByteData> load(String key) async {
    final encoded = _images[key];
    if (encoded == null) return await rootBundle.load(key);
    return ByteData.sublistView(base64Decode(encoded));
  }
}

const _images = <String, String>{
  'assets/icon/pip_emote_100_percent.png':
      '',
